css:
/* =========================================================
   ARM ARCHITECTURE & CONSTRUCTION
   CORPORATE LETTER FORMAT
   ERPNext v15 / wkhtmltopdf SAFE
   ========================================================= */


/* =========================================================
   PAGE
   ========================================================= */

@page {
    size: A4 portrait;
    margin: 14mm 15mm 12mm 15mm;
}


/* =========================================================
   GLOBAL RESET
   ========================================================= */

html,
body,
.print-format,
.print-format-preview {
    margin: 0 !important;
    padding: 0 !important;
    background: #ffffff !important;
}

body {
    font-family:
        "DejaVu Sans",
        "Tahoma",
        "Arial",
        sans-serif !important;

    color: #1f2937 !important;
    background: #ffffff !important;

    font-size: 10.5pt !important;
    line-height: 1.8 !important;

    direction: rtl !important;

    -webkit-print-color-adjust: exact !important;
    print-color-adjust: exact !important;
}


/* =========================================================
   MAIN CONTAINER
   ========================================================= */

.arm-letter {
    width: 100%;
    margin: 0;
    padding: 0;

    direction: rtl;
    text-align: right;

    font-family:
        "DejaVu Sans",
        "Tahoma",
        "Arial",
        sans-serif;

    color: #1f2937;
    font-size: 10.5pt;
    line-height: 1.8;
}


/* =========================================================
   BOX SIZING
   ========================================================= */

.arm-letter *,
.arm-letter *:before,
.arm-letter *:after {
    box-sizing: border-box;
}


/* =========================================================
   HEADER
   ========================================================= */

.arm-header {
    width: 100%;

    margin: 0 0 0 0;
    padding: 0 0 10px 0;

    border-bottom: 2px solid #111827;

    page-break-inside: avoid;
    break-inside: avoid;
}


.arm-header-table {
    width: 100%;

    border-collapse: collapse;
    border-spacing: 0;

    table-layout: fixed;
}


.arm-header-table td {
    border: none !important;
    padding: 0 !important;

    vertical-align: middle;
}


/* Company side */

.arm-company {
    width: 82%;

    text-align: right;

    padding-right: 2px !important;
}


.company-name-ar {
    margin: 0;

    color: #111827;

    font-size: 18pt;
    font-weight: 800;

    line-height: 1.25;
}


.company-name-en {
    margin-top: 2px;

    color: #64748b;

    font-family: Arial, sans-serif;

    font-size: 7.5pt;
    font-weight: 700;

    letter-spacing: 1.8px;

    direction: ltr;
    text-align: right;
}


.company-department {
    margin-top: 5px;

    color: #475569;

    font-size: 8.5pt;
}


/* Logo */

.arm-logo-cell {
    width: 18%;

    text-align: left;

    direction: ltr;
}


.arm-logo {
    width: 58px;
    height: 58px;

    object-fit: contain;

    display: inline-block;

    border: none;
}


/* =========================================================
   DOCUMENT INFORMATION BAR
   ========================================================= */

.document-info {
    width: 100%;

    margin: 0 0 20px 0;

    border-bottom: 1px solid #d1d5db;

    background: #f8fafc;

    page-break-inside: avoid;
}


.info-table {
    width: 100%;

    border-collapse: collapse;
    border-spacing: 0;

    table-layout: fixed;
}


.info-table td {
    border: none !important;

    border-left: 1px solid #d1d5db !important;

    padding: 7px 9px !important;

    vertical-align: middle;

    text-align: right;
}


.info-table td:first-child {
    border-right: none !important;
}


.info-table td:last-child {
    border-left: none !important;
}


.info-cell {
    font-size: 8.5pt;

    white-space: nowrap;
}


.info-label {
    color: #64748b;

    font-weight: 500;

    margin-left: 5px;
}


.info-value {
    color: #111827;

    font-weight: 700;
}


.ltr {
    direction: ltr;
    unicode-bidi: embed;
}


.priority-cell {
    text-align: center !important;
}


.priority {
    display: inline-block;

    padding: 1px 7px;

    background: #e5e7eb;

    color: #374151;

    border-radius: 2px;

    font-size: 8pt;

    font-weight: 700;
}


.priority.urgent {
    background: #111827;

    color: #ffffff;
}


/* =========================================================
   RECIPIENT
   ========================================================= */

.recipient-section {
    margin: 0 0 18px 0;

    page-break-inside: avoid;
    break-inside: avoid;
}


.recipient-row {
    margin-bottom: 5px;

    font-size: 11.5pt;

    color: #111827;
}


.recipient-label {
    color: #64748b;

    font-weight: 500;

    margin-left: 7px;
}


.recipient-name {
    color: #111827;

    font-weight: 700;
}


.recipient-department {
    color: #64748b;

    font-size: 9.5pt;

    margin-right: 5px;
}


.salutation {
    color: #374151;

    font-size: 10pt;

    margin-top: 5px;
}


/* =========================================================
   SUBJECT
   ========================================================= */

.subject-box {
    width: 100%;

    display: table;

    margin: 0 0 24px 0;

    border: 1px solid #d1d5db;

    background: #ffffff;

    page-break-inside: avoid;
    break-inside: avoid;
}


.subject-label,
.subject-value {
    display: table-cell;

    vertical-align: middle;
}


.subject-label {
    width: 90px;

    background: #111827;

    color: #ffffff;

    padding: 8px 12px;

    font-size: 10pt;

    font-weight: 700;

    text-align: center;

    white-space: nowrap;
}


.subject-value {
    padding: 8px 14px;

    color: #111827;

    font-size: 10.5pt;

    font-weight: 700;

    text-align: right;
}


/* =========================================================
   LETTER BODY
   ========================================================= */

.letter-body {
    width: 100%;

    color: #1f2937;

    font-size: 10.5pt;

    line-height: 2;

    text-align: justify;

    text-justify: inter-word;

    margin: 0 0 25px 0;

    overflow-wrap: break-word;
}


/*
   The rich text coming from ERPNext may contain
   paragraphs, divs, lists, tables, etc.
*/

.letter-body p {
    margin: 0 0 14px 0;

    text-align: justify;

    orphans: 3;
    widows: 3;
}


.letter-body div {
    max-width: 100%;
}


.letter-body ul,
.letter-body ol {
    margin-top: 8px;
    margin-bottom: 15px;

    padding-right: 25px;
}


.letter-body li {
    margin-bottom: 5px;
}


.letter-body strong {
    color: #111827;
}


/* =========================================================
   ATTACHMENTS
   ========================================================= */

.attachments-section {
    margin-top: 20px;
    margin-bottom: 25px;

    page-break-inside: auto;
}


.section-heading {
    margin-bottom: 9px;

    padding-right: 9px;

    border-right: 3px solid #111827;

    color: #111827;

    font-size: 10.5pt;

    font-weight: 800;

    line-height: 1.4;

    page-break-after: avoid;
}


.attachments-table {
    width: 100%;

    border-collapse: collapse;

    table-layout: fixed;

    page-break-inside: auto;
}


.attachments-table thead {
    display: table-header-group;
}


.attachments-table tr {
    page-break-inside: avoid !important;
    break-inside: avoid !important;
}


.attachments-table th {
    background: #f3f4f6;

    color: #111827;

    font-size: 8.5pt;

    font-weight: 700;

    padding: 7px 8px;

    border-top: 1px solid #9ca3af;
    border-bottom: 1px solid #9ca3af;
    border-left: 1px solid #d1d5db;

    text-align: right;
}


.attachments-table th:first-child {
    border-right: 1px solid #d1d5db;
}


.attachments-table td {
    padding: 7px 8px;

    border-bottom: 1px solid #e5e7eb;
    border-left: 1px solid #e5e7eb;

    color: #374151;

    font-size: 8.5pt;

    vertical-align: middle;
}


.attachments-table td:first-child {
    border-right: 1px solid #e5e7eb;
}


.col-number {
    width: 11%;
}


.col-type {
    width: 14%;
}


.center {
    text-align: center !important;
}


/* =========================================================
   CLOSING
   ========================================================= */

.closing-section {
    margin-top: 35px;

    page-break-inside: avoid;
    break-inside: avoid;
}


.closing-text {
    margin-bottom: 28px;

    color: #374151;

    font-size: 10.5pt;

    font-weight: 500;
}


/* =========================================================
   SIGNATURES
   ========================================================= */

.signatures-table {
    width: 100%;

    border-collapse: collapse;

    table-layout: fixed;
}


.signatures-table td {
    border: none !important;

    padding: 0 !important;

    vertical-align: top;
}


.signature-column {
    width: 38%;

    text-align: center;
}


.signature-gap {
    width: 24%;
}


.signature-title {
    color: #111827;

    font-size: 9.5pt;

    font-weight: 700;

    margin-bottom: 10px;
}


.signature-space {
    height: 48px;

    margin: 0 18px 7px 18px;

    border-bottom: 1px solid #6b7280;
}


.signature-name {
    color: #111827;

    font-size: 9.5pt;

    font-weight: 700;
}


.signature-role {
    margin-top: 2px;

    color: #64748b;

    font-size: 8pt;
}


/* =========================================================
   FOOTER
   ========================================================= */

.arm-footer {
    margin-top: 25px;

    padding-top: 7px;

    border-top: 1px solid #9ca3af;

    color: #64748b;

    font-size: 7pt;

    text-align: center;

    direction: rtl;

    page-break-inside: avoid;
}


.footer-separator {
    margin: 0 7px;

    color: #cbd5e1;
}


/* =========================================================
   PAGE BREAK CONTROL
   ========================================================= */

.no-break {
    page-break-inside: avoid !important;
    break-inside: avoid !important;
}


.page-break {
    page-break-before: always !important;
    break-before: page !important;
}


/* =========================================================
   PRINT
   ========================================================= */

@media print {

    html,
    body {
        background: #ffffff !important;
    }

    .arm-letter {
        width: 100% !important;
    }

    .arm-header,
    .document-info,
    .recipient-section,
    .subject-box,
    .closing-section {
        page-break-inside: avoid !important;
    }

}
